```bash
cat <<'EOF' > comprehensive_test.py
import parse

# Test the trailing newline issue
r = parse.parse('{}', 'test\n')
if r:
    print(f"Trailing newline test: {repr(r[0])}")
else:
    print("Trailing newline test: Failed to parse")

# Test the invalid group names issue
try:
    result = parse.parse("{hello['world']}", "doesn't work")
    if result:
        print(f"Invalid group names test: {result[0]}")
    else:
        print("Invalid group names test: Failed to parse")
except Exception as e:
    print(f"Exception: {e}")

# Test with other special characters
try:
    result = parse.parse("{field-with.dots}", "test value")
    if result:
        print(f"Special characters test: {result.named}")
    else:
        print("Special characters test: Failed to parse")
except Exception as e:
    print(f"Exception: {e}")

# Test with nested brackets and quotes
try:
    result = parse.parse("{user['profile']['name']}", "John Doe")
    if result:
        print(f"Nested brackets test: {result[0]}")
    else:
        print("Nested brackets test: Failed to parse")
except Exception as e:
    print(f"Exception: {e}")

print("All tests completed!")
EOF
